from pathlib import Path
import subprocess,json,gzip,base64,hashlib,shutil,time
r=Path('/mnt/development/projects/worktrees/Maktabah-wave3-history-records-20261127')
assert shutil.disk_usage(r).free>288*1024*1024,shutil.disk_usage(r).free
files=json.loads(gzip.decompress(base64.b64decode('')))
for f in files:(r/f['path']).write_text(f['source'])
root=r/'docs/hq-ui-inventory/wave3-history-records-20261127/publication-controls'
out=root/'attempt-3'
assert not out.exists();out.mkdir()
gen=r/'docs/hq-ui-inventory/wave3-history-records-20261127/make-publication-controls.py'
a=subprocess.run(['python3',str(gen),str(r),str(out)],text=True,capture_output=True)
(out/'generate.stdout.log').write_text(a.stdout);(out/'generate.stderr.log').write_text(a.stderr)
assert a.returncode==0,a.stderr
inputs=json.loads((out/'SOURCE_INPUTS.json').read_text())
for x in inputs['inputs']:
 dst=out/'inputs'/x['path'];dst.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(r/x['path'],dst)
cache='/mnt/development/projects/diagnostics/otzaria-wave3-search-entry-20261127/module-cache'
def run(where):
 free=shutil.disk_usage(r).free;assert free>280*1024*1024,free
 binary=where/'publication-controls'
 cmd=['/usr/local/bin/swiftc','-swift-version','6','-parse-as-library','-module-cache-path',cache,str(where/'Controls.swift'),'-o',str(binary)]
 started=time.time();a=subprocess.run(cmd,text=True,capture_output=True,timeout=40)
 (where/'compile.stdout.log').write_text(a.stdout);(where/'compile.stderr.log').write_text(a.stderr)
 res={'command':cmd,'compile_exit':a.returncode,'compile_seconds':time.time()-started,'free_before':free,'free_after':shutil.disk_usage(r).free,'source_sha256':hashlib.sha256((where/'Controls.swift').read_bytes()).hexdigest(),'scope':'actual source/domain component; no SDK/app/Core/native claim'}
 if a.returncode==0:
  q=subprocess.run([str(binary),str(where/'fixture-data')],text=True,capture_output=True,timeout=20)
  (where/'run.stdout.log').write_text(q.stdout);(where/'run.stderr.log').write_text(q.stderr)
  res.update(run_exit=q.returncode,result_line=q.stdout.strip().splitlines()[-1] if q.stdout.strip() else None,failed_cases=[x for x in q.stdout.splitlines() if x.startswith('FAIL ')],binary_sha256=hashlib.sha256(binary.read_bytes()).hexdigest())
 else:res['compile_stderr']=a.stderr
 (where/'RESULT.json').write_text(json.dumps(res,indent=2)+'\n')
 return res
candidate=run(out);assert candidate.get('run_exit')==0,candidate
original=(out/'Controls.swift').read_text()
negatives={}
for name,old,new in [
 ('negative-store-publications','        publicationSource.willChange()','        // NEGATIVE CONTROL: original mutation without publication retirement'),
 ('negative-load-provenance','        guard let revision = load.revision, qualifiedLoadRevision == revision,','        guard let revision = load.revision, revision == revision,')]:
 d=root/name;assert not d.exists();d.mkdir()
 changed=original.replace(old,new)
 if name=='negative-load-provenance':
  changed=changed.replace('&& source.generation == generation && source.activeTransitionToken == transition','&& source.generation == source.generation && source.activeTransitionToken == source.activeTransitionToken')
 assert changed!=original
 (d/'Controls.swift').write_text(changed)
 (d/'COUNTERFACTUAL.json').write_text(json.dumps({'candidate':'attempt-3/Controls.swift','boundary':'Deliberate metadata-fence removal only. Never shipped or used to claim product acceptance.','replaced':old,'replacement':new},indent=2)+'\n')
 negatives[name]=run(d)
 assert negatives[name].get('run_exit')==1,negatives[name]
print(json.dumps({'candidate':candidate,'negatives':negatives,'freeBytes':shutil.disk_usage(r).free}))
